 if(v.kind==='vertical'){const r=v.angle*Math.PI/180,cx=250,cy=155,dx=180*Math.cos(r),dy=180*Math.sin(r);path('M50 155 H450');path(`M${cx-dx} ${cy+dy} L${cx+dx} ${cy-dy}`);path(`M${cx+35} ${cy} A35 35 0 0 0 ${cx+35*Math.cos(r)} ${cy-35*Math.sin(r)}`);path(`M${cx-35} ${cy} A35 35 0 0 0 ${cx-35*Math.cos(r)} ${cy+35*Math.sin(r)}`);label(cx+65*Math.cos(r/2),cy-65*Math.sin(r/2),v.angle+'°');label(cx-65*Math.cos(r/2),cy+65*Math.sin(r/2),v.hideSecond?'?':v.angle+'°');label(250,285,'Vertically opposite angles');}
 if(v.kind==='bisector'){path('M60 190 H440');path('M250 40 V270');path('M250 170 H270 V190');label(60,220,'X');label(250,220,'O');label(440,220,'Y');label(155,175,v.length/2+' cm');label(345,175,v.length/2+' cm');label(320,45,'Perpendicular bisector');}
